"""Replayable, local syntax-only migration of exact Writing-owned generated bytes."""

from __future__ import annotations

import copy

from airesearcher.core.fsutil import atomic_write_bytes, sha256_bytes

from . import claims as binding
from . import latex_syntax, recovery
from .writer import SECTIONS, SectionOutput, _section_bytes


def finish(ctx, state, meta, pending, load, save, path):
    owned = {"paper/claims.jsonl", "paper/.writing/bound-claims.json"}
    owned.update(f"paper/sections/{name}.tex" for name in SECTIONS)
    owned.update(f"paper/.writing/section-{name}.json" for name in SECTIONS)
    if not pending.get("files") or not set(pending["files"]) <= owned:
        raise ValueError("Invalid Writing syntax-recovery target")
    # Check the entire transaction before any replacement; a later human edit
    # must never be mistaken for generated text that can be overwritten.
    for name, entry in pending["files"].items():
        target = path(ctx, name)
        current = target.read_bytes().hex() if target.exists() else None
        if current not in {entry["before"], entry["after"]}:
            raise recovery.ReconcileRequired("file changed during syntax-only recovery",
                                            {name: bytes.fromhex(entry["before"])})
    for name, entry in pending["files"].items():
        target = path(ctx, name)
        after = bytes.fromhex(entry["after"])
        if not target.exists() or target.read_bytes() != after:
            atomic_write_bytes(target, after)
    history = meta.setdefault("syntax_repairs", [])
    if pending["id"] not in history:
        history.append(pending["id"])
    meta.pop("compiled", None)
    state["phase"] = "write"
    save(ctx, "runtime", meta)
    pending["done"] = True
    save(ctx, "syntax-repair-" + pending["id"], pending)
    save(ctx, "pending-syntax", pending)
    ctx.log("Deterministic LaTeX literal escaping applied to generated Writing files; "
            "claim evidence and numeric values unchanged; no model call: " + ", ".join(pending["files"]))


def repair_owned(ctx, state, meta, writer, load, save, path, hash_value):
    if state.get("phase") not in {"write", "compile", "compile_fix"}:
        return False
    old_claims = writer.claims
    new_claims = None if old_claims is None else [
        c.model_copy(update={"text": latex_syntax.normalize(c.text, claim=True)}) for c in old_claims
    ]
    new_writer = copy.copy(writer)
    new_writer.claims = new_claims
    targets = {}

    def add(name, content):
        target = path(ctx, name)
        before = target.read_bytes() if target.exists() else None
        if before != content:
            if before is None:
                raise ValueError("Syntax recovery requires an existing owned file: " + name)
            targets[name] = {"before": before.hex(), "after": content.hex()}

    def encoded(value):
        # Match the normal receipt writer, including UTF-8 and its final newline.
        from airesearcher.core.fsutil import dumps

        return (dumps(value) + "\n").encode("utf-8")

    for name in SECTIONS:
        receipt = load(ctx, "section-" + name)
        target = path(ctx, f"paper/sections/{name}.tex")
        if not receipt or not target.exists():
            continue
        expected_fingerprint = hash_value([writer.section_fingerprint(name), state["writing_config"],
                                           state["figures"] if old_claims is None else None])
        if receipt.get("fingerprint") != expected_fingerprint:
            continue  # Normal factual/prompt invalidation owns regeneration.
        output = SectionOutput.model_validate(receipt["output"])
        original = target.read_bytes()
        normalized = latex_syntax.normalize(output.latex)
        claim_changed = any(a.text != b.text for a, b in zip(old_claims or [], new_claims or [], strict=True)
                            if a.section == name)
        if normalized == output.latex and not claim_changed:
            continue
        if (receipt.get("human_edited") or sha256_bytes(original) != receipt.get("file_sha256")
                or original != _section_bytes(output)):
            raise recovery.ReconcileRequired("syntax repair intersects an edited section; preserve edits",
                                            {f"paper/sections/{name}.tex": _section_bytes(output)})
        if old_claims is not None:
            binding.validate_bound_section(output.latex, old_claims, name)
        repaired = output.model_copy(update={"latex": normalized})
        new_writer.validate_section(repaired, name)
        updated = {**receipt, "output": repaired.model_dump(), "installed": True,
                   "file_sha256": sha256_bytes(_section_bytes(repaired)),
                   "context_sha256": new_writer.section_fingerprint(name),
                   "fingerprint": hash_value([new_writer.section_fingerprint(name), state["writing_config"],
                                               state["figures"] if new_claims is None else None]),
                   "syntax_normalized": True}
        add(f"paper/sections/{name}.tex", _section_bytes(repaired))
        add(f"paper/.writing/section-{name}.json", encoded(updated))
    if new_claims != old_claims:
        # A canonical text escape must never alter values, selectors or evidence.
        for old, new in zip(old_claims, new_claims, strict=True):
            if old.model_dump(exclude={"text"}) != new.model_dump(exclude={"text"}):
                raise ValueError("Syntax recovery attempted to alter claim evidence")
        if binding.values_tex(old_claims) != binding.values_tex(new_claims):
            raise ValueError("Syntax recovery attempted to alter numeric values")
        bound = load(ctx, "bound-claims")
        bound["claims"] = [c.model_dump(mode="json") for c in new_claims]
        add("paper/claims.jsonl", binding.claims_bytes(new_claims))
        add("paper/.writing/bound-claims.json", encoded(bound))
    if not targets:
        return False
    pending = {"id": hash_value(targets), "files": targets, "done": False,
               "description": "Only deterministic literal escaping; original bytes retained below"}
    # Save all original bytes and all validated replacements before changing any
    # file, so interruption cannot leave claims and sections permanently out of sync.
    save(ctx, "pending-syntax", pending)
    finish(ctx, state, meta, pending, load, save, path)
    return True
